import numpy as np
from scipy.optimize import least_squares
def mk(extra):
    def f(p):
        a,b,c,d,e,f_,g,w,ph=p[:9]
        base=a+b*P+c*P**2+d*t+e*t*P+(f_+g*P)*np.sin(w*t+ph)
        if extra: base=base+p[9]*P**3+p[10]*np.log(P)
        return base
    return f
